# Generated by build.py from recipe.yml for recipe surl-seed-a-mailbox-before-a-test. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:secret', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS -u ann@example.com:secret --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[01-10].eml" smtp://127.0.0.1:8080/example.com
try { curl.exe -sS -u ann@example.com:secret -X "SEARCH UNSEEN" imap://127.0.0.1:8081/INBOX } finally { Stop-Process $server0 }
